package cn.servicehub.workflow.team;
import java.util.List;import java.util.Map;import java.util.Optional;import java.util.concurrent.ConcurrentHashMap;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Repository;
@Repository @Profile("!mysql") public class InMemorySupportQueueMigrationRepository implements SupportQueueMigrationRepository{private final Map<String,SupportQueueMigrationPlan>plans=new ConcurrentHashMap<>();private final Map<String,SupportQueueMigrationPlanItem>items=new ConcurrentHashMap<>();public Optional<SupportQueueMigrationPlan>findPlan(String id){return Optional.ofNullable(plans.get(id));}public Optional<SupportQueueMigrationPlan>findActiveBySource(String source){return plans.values().stream().filter(p->p.sourceQueueCode().equals(source)&&java.util.Set.of(SupportQueueMigrationPlanStatus.PENDING_APPROVAL,SupportQueueMigrationPlanStatus.APPROVED,SupportQueueMigrationPlanStatus.EXECUTING,SupportQueueMigrationPlanStatus.PARTIALLY_COMPLETED).contains(p.status())).findFirst();}public List<SupportQueueMigrationPlanItem>findItems(String id){return items.entrySet().stream().filter(e->e.getKey().startsWith(id+":" )).map(Map.Entry::getValue).sorted(java.util.Comparator.comparing(SupportQueueMigrationPlanItem::itemId)).toList();}public synchronized void create(SupportQueueMigrationPlan p,List<SupportQueueMigrationPlanItem>list){if(findActiveBySource(p.sourceQueueCode()).isPresent()||plans.putIfAbsent(p.id(),p)!=null)throw new cn.servicehub.workflow.application.WorkflowConflictException();list.forEach(i->items.put(p.id()+":"+i.itemId(),i));}public synchronized boolean updatePlan(SupportQueueMigrationPlan p,long v,SupportQueueMigrationPlanStatus s){SupportQueueMigrationPlan old=plans.get(p.id());if(old==null||old.planVersion()!=v||old.status()!=s)return false;plans.put(p.id(),p);return true;}public synchronized boolean updateItem(String plan,SupportQueueMigrationPlanItem item,long v,SupportQueueMigrationItemStatus s){String k=plan+":"+item.itemId();SupportQueueMigrationPlanItem old=items.get(k);if(old==null||old.version()!=v||old.status()!=s)return false;items.put(k,item);return true;}}
